"use client";
import { cn } from "@/lib/utils";

import { useState } from "react";
import { Check, Layers2 } from "lucide-react";
import { ElasticIndicator } from "@/lib/takt-indicator";
import { panel } from "@/lib/takt-surface";
const rates = [
  { monthly: 1200, total: 1200 },
  { monthly: 1000, total: 12000 },
];
const number = new Intl.NumberFormat("en-US");
export function PlanSwitch({
  className,
  options = ["Month", "Year"],
  prices = rates,
  onChange,
}: {
  className?: string;
  options?: string[];
  prices?: { monthly: number; total: number }[];
  onChange?: (index: number) => void;
}) {
  const [index, setIndex] = useState(0);
  const selected = Math.min(index, Math.max(0, options.length - 1));
  const price = options.length ? prices[selected] : undefined;
  const base = prices[0]?.monthly;
  const saving =
    price && base > 0 ? Math.round((1 - price.monthly / base) * 100) : 0;
  return (
    <section className={cn(panel + " w-64 max-w-full", className)}>
      <header className="flex items-center gap-2">
        <span className="grid size-8 place-items-center rounded-xl bg-primary text-primary-foreground">
          <Layers2 size={16} />
        </span>
        <strong className="text-base tracking-tight">Studio</strong>
        {saving > 0 && (
          <span className="ml-auto rounded-full bg-primary/10 px-2 py-0.5 text-[11px] font-semibold text-primary">
            −{saving}%
          </span>
        )}
      </header>
      <div
        role="group"
        aria-label="Billing period"
        className="relative my-3 flex rounded-full border border-foreground/5 bg-muted p-1"
      >
        <span aria-hidden className="absolute inset-1 rounded-full">
          <ElasticIndicator
            count={options.length}
            index={selected}
            className="bg-card shadow-sm"
          />
        </span>
        {options.map((opt, i) => (
          <button
            key={opt}
            type="button"
            aria-pressed={selected === i}
            className={
              "relative flex-1 rounded-full px-2 py-1.5 text-xs " +
              (i === selected ? "font-semibold text-primary" : "text-foreground/75")
            }
            onClick={() => {
              setIndex(i);
              onChange?.(i);
            }}
          >
            {opt}
          </button>
        ))}
      </div>
      {price && (
        <div aria-live="polite">
          <div
            key={selected}
            className="motion-safe:animate-in motion-safe:slide-in-from-bottom-1"
          >
            <strong className="text-[28px] leading-tight font-semibold tracking-tight tabular-nums">
              {number.format(price.monthly)} ₽
            </strong>
            <span className="ml-1 text-xs text-muted-foreground">/ mo.</span>
          </div>
          <span className="mt-1 flex items-center gap-1.5 text-[11px] text-muted-foreground">
            <Check size={13} />Total due {number.format(price.total)} ₽
          </span>
        </div>
      )}
    </section>
  );
}

"use client";

import { useLayoutEffect, useRef } from "react";

// The advancing edge reaches its stop before the trailing edge catches up.
export function ElasticIndicator({
  index,
  count,
  className = "bg-primary",
}: {
  index: number;
  count: number;
  className?: string;
}) {
  const pill = useRef<HTMLSpanElement>(null);
  const previous = useRef(index);
  useLayoutEffect(() => {
    const node = pill.current;
    if (!node || !count) return;
    const slot = Math.min(count - 1, Math.max(0, index));
    node.style.transitionDuration =
      slot >= previous.current ? "370ms, 190ms" : "190ms, 370ms";
    node.style.left = (100 * slot) / count + "%";
    node.style.right = (100 * (count - slot - 1)) / count + "%";
    previous.current = slot;
  }, [index, count]);
  return count > 0 ? (
    <span
      aria-hidden
      ref={pill}
      className={
        "pointer-events-none absolute inset-y-0 rounded-[inherit] ease-[cubic-bezier(.19,1,.32,1)] motion-safe:transition-[left,right] motion-reduce:transition-none! motion-reduce:duration-0! " +
        className
      }
    />
  ) : null;
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
